'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';

export default function PageEditor({ params }: { params: { id: string } }) {
    const router = useRouter();
    const supabase = createClient();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    const [title, setTitle] = useState('');
    const [slug, setSlug] = useState('');
    const [content, setContent] = useState('');
    const [isPublished, setIsPublished] = useState(false);

    useEffect(() => {
        const fetchPage = async () => {
            const { data, error } = await supabase
                .from('pages')
                .select('*')
                .eq('id', params.id)
                .single();

            if (data) {
                setTitle(data.title);
                setSlug(data.slug);
                setContent(data.content || '');
                setIsPublished(data.is_published);
            }
            setLoading(false);
        };
        fetchPage();
    }, [params.id]);

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        const { error } = await supabase
            .from('pages')
            .update({
                title,
                content, // In a real app, use a Rich Text Editor (e.g., TipTap)
                is_published: isPublished,
                updated_at: new Date().toISOString()
            })
            .eq('id', params.id);

        if (error) {
            toast.error('Failed to save page');
        } else {
            toast.success('Page saved successfully');
            router.refresh();
        }
        setSaving(false);
    };

    if (loading) return <div>Loading...</div>;

    return (
        <div className="container mx-auto px-6 py-8">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold tracking-tight text-gray-900">Edit Page: {title}</h1>
                <div className="flex gap-2">
                    <Button variant="outline" onClick={() => router.back()}>Cancel</Button>
                    <Button onClick={handleSave} disabled={saving}>{saving ? 'Saving...' : 'Save Changes'}</Button>
                </div>
            </div>

            <div className="grid gap-6 max-w-4xl">
                <div className="grid gap-2">
                    <Label>Page Title</Label>
                    <Input value={title} onChange={(e) => setTitle(e.target.value)} />
                </div>

                <div className="grid gap-2">
                    <Label>URL Slug</Label>
                    <Input value={slug} disabled className="bg-gray-100" />
                </div>

                <div className="grid gap-2">
                    <Label>Content (HTML Supported)</Label>
                    <Textarea
                        value={content}
                        onChange={(e) => setContent(e.target.value)}
                        className="min-h-[400px] font-mono"
                    />
                    <p className="text-xs text-gray-500">
                        Supports basic HTML (e.g., &lt;h1&gt;, &lt;p&gt;, &lt;strong&gt;, &lt;ul&gt;).
                    </p>
                </div>

                <div className="flex items-center space-x-2">
                    <Switch id="published" checked={isPublished} onCheckedChange={setIsPublished} />
                    <Label htmlFor="published">Published (Visible to public)</Label>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Loader2, Phone, Mail, Timer, ArrowRight } from 'lucide-react';
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp"

export default function SignupPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const supabase = createClient();
  const [loading, setLoading] = useState(false);

  // Phone Auth State
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [otpSent, setOtpSent] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Email Auth State (Fallback)
  const [showEmailSignup, setShowEmailSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');

  // Timer Logic
  useEffect(() => {
    if (timeLeft > 0) {
      timerRef.current = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
    } else if (timeLeft === 0 && timerRef.current) {
      clearTimeout(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [timeLeft]);

  // Auto-submit OTP
  useEffect(() => {
    if (otp.length === 6) {
      handleVerifyOtp(new Event('submit') as any);
    }
  }, [otp]);

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();

    // Simple validation for 10 digits
    if (!/^\d{10}$/.test(phone)) {
      toast.error('Please enter a valid 10-digit mobile number');
      return;
    }

    setLoading(true);
    const fullPhoneNumber = `+91${phone}`;

    try {
      const { error } = await supabase.auth.signInWithOtp({
        phone: fullPhoneNumber,
      });

      if (error) {
        if (error.message.includes('rate limit')) {
          throw new Error('Too many requests. Please try again later.');
        }
        throw error;
      }

      setOtpSent(true);
      setTimeLeft(60);
      toast.success('OTP sent!', { description: `Sent to ${fullPhoneNumber}` });
    } catch (error: any) {
      toast.error(error.message || 'Failed to send OTP');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    if (e.preventDefault) e.preventDefault();
    if (loading || otp.length !== 6) return;

    setLoading(true);
    const fullPhoneNumber = `+91${phone}`;

    try {
      const { error } = await supabase.auth.verifyOtp({
        phone: fullPhoneNumber,
        token: otp,
        type: 'sms',
      });

      if (error) throw error;

      toast.success('Account created successfully!');
      const next = searchParams.get('next') || '/';
      router.push(next);
      router.refresh();
    } catch (error: any) {
      toast.error(error.message || 'Invalid or expired OTP');
      setOtp('');
    } finally {
      setLoading(false);
    }
  };

  const handleResendOtp = async () => {
    if (timeLeft > 0) return;
    await handleSendOtp({ preventDefault: () => { } } as React.FormEvent);
  };

  const handleEmailSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            full_name: fullName,
          },
        },
      });

      if (authError) throw authError;

      if (authData.user) {
        toast.success('Account created successfully!');
        const next = searchParams.get('next') || '/';
        router.push(next);
        router.refresh();
      }
    } catch (error: any) {
      toast.error(error.message || 'Signup failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mx-auto px-4 py-16 flex justify-center items-center min-h-[60vh]">
      <Card className="w-full max-w-md shadow-lg border-stone-paper">
        <CardHeader className="text-center space-y-2">
          <CardTitle className="text-2xl font-serif text-deep-forest">
            {showEmailSignup ? 'Create Account' : (otpSent ? 'Verify Mobile' : 'Join Root & Loom')}
          </CardTitle>
          <CardDescription>
            {showEmailSignup
              ? 'Sign up with email to start shopping'
              : (otpSent ? `Enter code sent to +91 ${phone}` : 'Enter your mobile number to create an account')}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {!showEmailSignup ? (
            // Phone Signup (Same as login basically)
            <div className="space-y-6">
              {!otpSent ? (
                <form onSubmit={handleSendOtp} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="phone" className="text-deep-forest">Mobile Number</Label>
                    <div className="flex">
                      <div className="flex items-center justify-center px-3 border border-r-0 rounded-l-md bg-stone-paper/50 text-slate-bark text-sm font-medium">
                        +91
                      </div>
                      <Input
                        id="phone"
                        type="tel"
                        value={phone}
                        onChange={(e) => {
                          const val = e.target.value.replace(/\D/g, '').slice(0, 10);
                          setPhone(val);
                        }}
                        className="rounded-l-none"
                        placeholder="98765 43210"
                        required
                        autoFocus
                      />
                    </div>
                  </div>
                  <Button type="submit" className="w-full bg-deep-forest hover:bg-deep-forest/90 text-white" disabled={loading || phone.length < 10}>
                    {loading ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                        Sending OTP...
                      </>
                    ) : (
                      <>
                        Get OTP <ArrowRight className="ml-2 h-4 w-4" />
                      </>
                    )}
                  </Button>
                </form>
              ) : (
                <form onSubmit={handleVerifyOtp} className="space-y-6">
                  <div className="flex justify-center">
                    <InputOTP
                      maxLength={6}
                      value={otp}
                      onChange={(value) => setOtp(value)}
                    >
                      <InputOTPGroup>
                        <InputOTPSlot index={0} />
                        <InputOTPSlot index={1} />
                        <InputOTPSlot index={2} />
                        <InputOTPSlot index={3} />
                        <InputOTPSlot index={4} />
                        <InputOTPSlot index={5} />
                      </InputOTPGroup>
                    </InputOTP>
                  </div>
                  <Button type="submit" className="w-full bg-deep-forest hover:bg-deep-forest/90 text-white" disabled={loading || otp.length < 6}>
                    {loading ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                        Verifying...
                      </>
                    ) : (
                      'Verify & Signup'
                    )}
                  </Button>

                  <div className="flex flex-col items-center gap-2 text-sm">
                    {timeLeft > 0 ? (
                      <span className="text-muted-foreground flex items-center gap-1">
                        <Timer className="w-3 h-3" /> Resend code in {timeLeft}s
                      </span>
                    ) : (
                      <Button
                        variant="link"
                        type="button"
                        onClick={handleResendOtp}
                        className="text-deep-forest p-0 h-auto"
                        disabled={loading}
                      >
                        Resend Code
                      </Button>
                    )}

                    <Button
                      variant="link"
                      type="button"
                      onClick={() => {
                        setOtpSent(false);
                        setOtp('');
                      }}
                      className="text-muted-foreground p-0 h-auto text-xs"
                    >
                      Change Phone Number
                    </Button>
                  </div>
                </form>
              )}

              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <span className="w-full border-t border-stone-paper" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-background px-2 text-muted-foreground">
                    Or
                  </span>
                </div>
              </div>

              <Button
                variant="outline"
                type="button"
                className="w-full border-deep-forest/20 text-deep-forest hover:bg-stone-paper/50"
                onClick={() => setShowEmailSignup(true)}
                disabled={loading}
              >
                <Mail className="mr-2 h-4 w-4" />
                Sign Up with Email
              </Button>
            </div>
          ) : (
            // Email Signup
            <div className="space-y-4">
              <form onSubmit={handleEmailSignup} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="fullName">Full Name</Label>
                  <Input
                    id="fullName"
                    type="text"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    placeholder="John Doe"
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input
                    id="email"
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="name@example.com"
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <Input
                    id="password"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Create a password (min. 6 characters)"
                    required
                    minLength={6}
                  />
                </div>
                <Button type="submit" className="w-full bg-deep-forest hover:bg-deep-forest/90 text-white" disabled={loading}>
                  {loading ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Creating account...
                    </>
                  ) : (
                    'Sign Up'
                  )}
                </Button>
              </form>

              <div className="relative my-4">
                <div className="absolute inset-0 flex items-center">
                  <span className="w-full border-t border-stone-paper" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-background px-2 text-muted-foreground">
                    Or return to
                  </span>
                </div>
              </div>

              <Button
                variant="outline"
                type="button"
                className="w-full border-deep-forest/20 text-deep-forest hover:bg-stone-paper/50"
                onClick={() => setShowEmailSignup(false)}
                disabled={loading}
              >
                <Phone className="mr-2 h-4 w-4" />
                Sign Up with Phone
              </Button>
            </div>
          )}

          <div className="mt-6 text-center text-sm">
            <span className="text-muted-foreground">Already have an account? </span>
            <Link href="/auth/login" className="font-semibold text-deep-forest hover:underline">
              Login
            </Link>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { createClient } from '@/lib/supabase/client';
import { useEffect, useState } from 'react';

export default function DebugRolePage() {
    const [data, setData] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const supabase = createClient();

    useEffect(() => {
        async function checkRole() {
            const { data: { user } } = await supabase.auth.getUser();

            if (!user) {
                setData({ error: 'Not logged in' });
                setLoading(false);
                return;
            }

            const { data: profile, error } = await supabase
                .from('profiles')
                .select('*')
                .eq('id', user?.id)
                .single();

            setData({
                user_email: user.email,
                user_id: user.id,
                profile_data: profile,
                profile_error: error,
                is_admin_check: profile?.role === 'admin'
            });
            setLoading(false);
        }

        checkRole();
    }, []);

    const makeAdmin = async () => {
        const { error } = await supabase
            .from('profiles')
            .update({ role: 'admin' })
            .eq('id', data.user_id);

        if (error) alert('Error: ' + error.message);
        else window.location.reload();
    };

    if (loading) return <div className="p-10">Loading debug info...</div>;

    return (
        <div className="p-10 font-mono text-sm max-w-4xl mx-auto">
            <h1 className="text-2xl font-bold mb-4">Role Debugger</h1>
            <pre className="bg-slate-100 p-4 rounded border">
                {JSON.stringify(data, null, 2)}
            </pre>
            <div className="mt-4 p-4 border rounded bg-yellow-50">
                <h2 className="font-bold">Interpretation:</h2>
                <ul className="list-disc ml-5 mt-2">
                    <li>If <strong>profile_data</strong> is null, the profile row doesn&apos;t exist.</li>
                    <li>If <strong>profile_data.role</strong> is &quot;user&quot;, the SQL update didn&apos;t run.</li>
                    <li>If <strong>is_admin_check</strong> is false, the header won&apos;t show the link.</li>
                </ul>
                <div className="mt-4 border-t pt-4">
                    <button
                        onClick={makeAdmin}
                        className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
                    >
                        Force Make Me Admin (Dev Only)
                    </button>
                    <p className="text-xs text-gray-500 mt-1">This works because RLS currently allows self-update.</p>
                </div>
            </div>
        </div>
    );
}

import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { FileQuestion } from 'lucide-react';

export default function NotFound() {
    return (
        <div className="container mx-auto px-4 py-32 flex flex-col items-center justify-center min-h-[60vh] text-center">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                <FileQuestion className="h-10 w-10 text-slate-400" />
            </div>
            <h1 className="text-4xl font-playfair font-bold text-deep-forest mb-4">Page Not Found</h1>
            <p className="text-slate-500 mb-8 max-w-md mx-auto">
                Sorry, we couldn't find the page you're looking for. It might have been moved, deleted, or never existed.
            </p>
            <div className="flex gap-4">
                <Button asChild variant="default" className="bg-deep-forest hover:bg-deep-forest/90">
                    <Link href="/">Back to Home</Link>
                </Button>
                <Button asChild variant="outline">
                    <Link href="/shop">Browse Shop</Link>
                </Button>
            </div>
        </div>
    );
}

import { createClient } from '@/lib/supabase/server';
import { ProductCard } from '@/components/product/product-card';
import { Filter, X, ChevronDown, SlidersHorizontal, Search, Home, ChevronRight, ArrowLeft } from 'lucide-react';
import { redirect } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Sheet, SheetContent, SheetTrigger, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import { Suspense } from 'react';
import SearchLoading from './loading';
import SearchSort from './search-sort';

export const metadata = {
    title: 'Search Results | Root & Loom',
    description: 'Find premium sustainable fashion matching your style.',
};

type SearchPageProps = {
    searchParams: {
        q?: string;
        category?: string;
        minPrice?: string;
        maxPrice?: string;
        sort?: string;
        page?: string;
    };
};

interface SearchResult {
    id: string;
    name: string;
    slug: string;
    base_price: number;
    product_images: { image_url: string; alt_text: string | null }[];
    total_count: number;
}

export default async function SearchPage({ searchParams }: SearchPageProps) {
    const query = searchParams.q || '';
    const categoryFilter = searchParams.category;
    const minPrice = searchParams.minPrice ? parseFloat(searchParams.minPrice) : null;
    const maxPrice = searchParams.maxPrice ? parseFloat(searchParams.maxPrice) : null;
    const sortBy = searchParams.sort || 'relevance';
    const page = parseInt(searchParams.page || '1');
    const limit = 20;
    const offset = (page - 1) * limit;

    const supabase = await createClient();

    // Fetch categories for filter
    const { data: categories } = await supabase
        .from('categories')
        .select('id, name, slug')
        .order('name');

    // Fetch search results
    const { data: results, error } = await supabase.rpc('search_products', {
        query_text: query,
        filter_category_id: categoryFilter ? ((await supabase.from('categories').select('id').eq('slug', categoryFilter).single()) as any).data?.id : null,
        min_price: minPrice,
        max_price: maxPrice,
        sort_by: sortBy,
        limit_count: limit,
        offset_count: offset
    } as any) as { data: SearchResult[] | null, error: any };

    // Fetch recommended products for empty state
    let recommendedProducts: any[] = [];
    if (!results || results.length === 0) {
        const { data: recs } = await supabase
            .from('products')
            .select('id, name, slug, base_price, product_images(image_url, alt_text)')
            .eq('featured', true)
            .limit(4);
        recommendedProducts = recs || [];
    }

    if (error) {
        console.error('Search Page Error:', error);
    }

    const products = results || [];
    const totalCount = products[0]?.total_count || 0;
    const totalPages = Math.ceil(Number(totalCount) / limit);

    // Filter Sidebar Component
    const FilterSidebar = () => {
        const activeFiltersCount = (categoryFilter ? 1 : 0) + (minPrice || maxPrice ? 1 : 0);

        return (
            <div className="space-y-8">
                <div className="flex items-center justify-between">
                    <h3 className="font-bold text-deep-forest flex items-center gap-2">
                        <SlidersHorizontal className="w-4 h-4" /> Filters
                    </h3>
                    {activeFiltersCount > 0 && (
                        <Link href={`/search?q=${query}`} className="text-xs text-red-500 hover:underline">
                            Clear All
                        </Link>
                    )}
                </div>

                {/* Active Filters */}
                {activeFiltersCount > 0 && (
                    <div className="flex flex-wrap gap-2">
                        {categoryFilter && (
                            <Link href={`/search?q=${query}${minPrice ? `&minPrice=${minPrice}` : ''}${maxPrice ? `&maxPrice=${maxPrice}` : ''}${sortBy ? `&sort=${sortBy}` : ''}`}>
                                <Badge variant="secondary" className="gap-1 pl-2 pr-1 py-1 hover:bg-stone-200 cursor-pointer border border-stone-200">
                                    {(categories as any[])?.find((c: any) => c.slug === categoryFilter)?.name || categoryFilter} <X className="w-3 h-3" />
                                </Badge>
                            </Link>
                        )}
                        {(minPrice || maxPrice) && (
                            <Link href={`/search?q=${query}${categoryFilter ? `&category=${categoryFilter}` : ''}${sortBy ? `&sort=${sortBy}` : ''}`}>
                                <Badge variant="secondary" className="gap-1 pl-2 pr-1 py-1 hover:bg-stone-200 cursor-pointer border border-stone-200">
                                    Price: {minPrice ? `Γé╣${minPrice}` : '0'} - {maxPrice ? `Γé╣${maxPrice}` : 'Any'} <X className="w-3 h-3" />
                                </Badge>
                            </Link>
                        )}
                    </div>
                )}

                {/* Categories */}
                <div>
                    <h3 className="text-sm font-bold mb-4 uppercase tracking-wider text-slate-500">Categories</h3>
                    <div className="space-y-2">
                        <Link
                            href={`/search?q=${query}${minPrice ? `&minPrice=${minPrice}` : ''}${maxPrice ? `&maxPrice=${maxPrice}` : ''}${sortBy ? `&sort=${sortBy}` : ''}`}
                            className={cn(
                                "flex items-center justify-between text-sm py-1.5 px-2 rounded-md transition-colors",
                                !categoryFilter ? 'bg-stone-100 font-bold text-deep-forest' : 'text-slate-600 hover:bg-stone-50 hover:text-deep-forest'
                            )}
                        >
                            <span>All Categories</span>
                        </Link>
                        {categories?.map((cat: any) => (
                            <Link
                                key={cat.id}
                                href={`/search?q=${query}&category=${cat.slug}${minPrice ? `&minPrice=${minPrice}` : ''}${maxPrice ? `&maxPrice=${maxPrice}` : ''}${sortBy ? `&sort=${sortBy}` : ''}`}
                                className={cn(
                                    "flex items-center justify-between text-sm py-1.5 px-2 rounded-md transition-colors",
                                    categoryFilter === cat.slug ? 'bg-stone-100 font-bold text-deep-forest' : 'text-slate-600 hover:bg-stone-50 hover:text-deep-forest'
                                )}
                            >
                                <span>{cat.name}</span>
                                {categoryFilter === cat.slug && <ChevronRight className="w-3.5 h-3.5" />}
                            </Link>
                        ))}
                    </div>
                </div>

                {/* Price Range */}
                <div className="pt-4 border-t border-slate-100">
                    <h3 className="text-sm font-bold mb-4 uppercase tracking-wider text-slate-500">Price Range</h3>
                    <div className="space-y-2">
                        {[
                            { label: 'Under Γé╣1000', min: null, max: 1000 },
                            { label: 'Γé╣1000 - Γé╣2500', min: 1000, max: 2500 },
                            { label: 'Γé╣2500 - Γé╣5000', min: 2500, max: 5000 },
                            { label: 'Over Γé╣5000', min: 5000, max: null },
                        ].map((range, i) => {
                            const isActive = minPrice === range.min && maxPrice === range.max;
                            return (
                                <Link
                                    key={i}
                                    href={`/search?q=${query}${categoryFilter ? `&category=${categoryFilter}` : ''}&minPrice=${range.min || ''}&maxPrice=${range.max || ''}${sortBy ? `&sort=${sortBy}` : ''}`}
                                    className={cn(
                                        "flex items-center gap-3 text-sm py-1.5 group cursor-pointer",
                                        isActive ? "font-bold text-deep-forest" : "text-slate-600"
                                    )}
                                >
                                    <div className={cn(
                                        "w-4 h-4 rounded border flex items-center justify-center transition-colors",
                                        isActive ? "bg-deep-forest border-deep-forest" : "border-slate-300 group-hover:border-deep-forest"
                                    )}>
                                        {isActive && <div className="w-2 h-2 bg-white rounded-full" />}
                                    </div>
                                    <span>{range.label}</span>
                                </Link>
                            )
                        })}
                    </div>
                </div>
            </div>
        );
    };

    return (
        <Suspense fallback={<SearchLoading />}>
            <div className="container mx-auto px-4 py-8 min-h-screen">
                {/* Breadcrumb */}
                <div className="flex items-center text-xs text-slate-500 mb-6">
                    <Link href="/" className="hover:text-deep-forest flex items-center gap-1"><Home className="w-3 h-3" /> Home</Link>
                    <ChevronRight className="w-3 h-3 mx-1" />
                    <span className="font-medium text-slate-900">Search Results</span>
                    {query && (
                        <>
                            <ChevronRight className="w-3 h-3 mx-1" />
                            <span className="text-deep-forest truncate max-w-[200px]">"{query}"</span>
                        </>
                    )}
                </div>

                {/* Header */}
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8 pb-4 border-b border-stone-100">
                    <div className="flex-1">
                        <h1 className="text-2xl font-serif font-bold text-deep-forest flex items-center gap-2">
                            {query ? (
                                <>Results for <span className="italic text-primary">"{query}"</span></>
                            ) : 'All Products'}
                        </h1>
                        <p className="text-sm text-slate-500 mt-1">
                            {totalCount > 0 ? (
                                <>Showing <strong>{products.length}</strong> of <strong>{Number(totalCount)}</strong> results</>
                            ) : (
                                '0 results found'
                            )}
                        </p>
                    </div>

                    <div className="flex items-center gap-3 w-full md:w-auto">
                        {/* Mobile Filter Sheet */}
                        <Sheet>
                            <SheetTrigger asChild>
                                <Button variant="outline" className="md:hidden flex-1 gap-2 border-stone-200">
                                    <Filter className="w-4 h-4" /> Filters
                                </Button>
                            </SheetTrigger>
                            <SheetContent side="left" className="w-[300px] overflow-y-auto">
                                <SheetHeader className="mb-6 text-left">
                                    <SheetTitle className="font-serif text- deep-forest">Filters</SheetTitle>
                                </SheetHeader>
                                <FilterSidebar />
                            </SheetContent>
                        </Sheet>

                        {/* Sort Dropdown */}
                        <div className="flex items-center gap-2 flex-1 md:flex-none">
                            <span className="text-sm text-slate-500 whitespace-nowrap hidden sm:inline">Sort by:</span>
                            <SearchSort currentSort={sortBy} />
                        </div>
                    </div>
                </div>

                <div className="flex flex-col lg:flex-row gap-8">
                    {/* Desktop Sidebar */}
                    <aside className="hidden lg:block w-64 flex-shrink-0">
                        <div className="sticky top-24">
                            <FilterSidebar />
                        </div>
                    </aside>

                    {/* Main Content */}
                    <main className="flex-1">
                        {products.length > 0 ? (
                            <>
                                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-6">
                                    {products.map((product) => (
                                        <ProductCard key={product.id} product={product} highlight={query} />
                                    ))}
                                </div>

                                {/* Pagination (Simple) */}
                                {totalPages > 1 && (
                                    <div className="mt-12 flex justify-center gap-2">
                                        {page > 1 && (
                                            <Link href={`/search?q=${query}&page=${page - 1}${categoryFilter ? `&category=${categoryFilter}` : ''}${sortBy ? `&sort=${sortBy}` : ''}`}>
                                                <Button variant="outline" size="sm" className="gap-1">
                                                    <ArrowLeft className="w-4 h-4" /> Previous
                                                </Button>
                                            </Link>
                                        )}
                                        <div className="flex items-center gap-1 px-4 text-sm font-medium text-slate-600">
                                            Page {page} of {totalPages}
                                        </div>
                                        {page < totalPages && (
                                            <Link href={`/search?q=${query}&page=${page + 1}${categoryFilter ? `&category=${categoryFilter}` : ''}${sortBy ? `&sort=${sortBy}` : ''}`}>
                                                <Button variant="outline" size="sm" className="gap-1">
                                                    Next <ChevronRight className="w-4 h-4" />
                                                </Button>
                                            </Link>
                                        )}
                                    </div>
                                )}
                            </>
                        ) : (
                            <div className="flex flex-col items-center justify-center py-16 text-center">
                                <div className="bg-stone-50 p-6 rounded-full mb-6">
                                    <Search className="w-12 h-12 text-stone-300" />
                                </div>
                                <h2 className="text-xl font-bold text-deep-forest mb-2">
                                    No results found for "{query}"
                                </h2>
                                <p className="text-slate-500 max-w-md mb-8">
                                    We couldn't find any products matching your search. Try checking for typos or searching for a different category.
                                </p>

                                {/* Recommendations */}
                                {recommendedProducts.length > 0 && (
                                    <div className="w-full mt-8 pt-8 border-t border-stone-100">
                                        <h3 className="text-lg font-bold text-deep-forest mb-6 text-left">You might like these</h3>
                                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-left">
                                            {recommendedProducts.map(p => (
                                                <ProductCard key={p.id} product={{ ...p, id: p.id, name: p.name, slug: p.slug, base_price: p.base_price, product_images: p.product_images }} />
                                            ))}
                                        </div>
                                    </div>
                                )}

                                <Link href="/">
                                    <Button className="mt-8 bg-deep-forest hover:bg-deep-forest/90 text-white px-8">
                                        Return to Home
                                    </Button>
                                </Link>
                            </div>
                        )}
                    </main>
                </div>
            </div>
        </Suspense>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { ProductCard } from '@/components/product/product-card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Slider } from '@/components/ui/slider';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { createClient } from '@/lib/supabase/client';
import { formatPrice } from '@/lib/utils/format';
import { Loader2, SlidersHorizontal } from 'lucide-react';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/components/ui/sheet';

interface Category {
  id: string;
  name: string;
  slug: string;
}

interface Product {
  id: string;
  name: string;
  slug: string;
  base_price: number;
  product_images: Array<{ image_url: string; alt_text: string | null }>;
}

export function ShopContent({
  categories,
  searchParams,
}: {
  categories: Category[];
  searchParams: { [key: string]: string | string[] | undefined };
}) {
  const router = useRouter();
  const params = useSearchParams();
  const supabase = createClient();

  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [priceRange, setPriceRange] = useState([0, 5000]);
  const [selectedCategory, setSelectedCategory] = useState<string>(
    (params.get('category') as string) || 'all'
  );
  const [sortBy, setSortBy] = useState<string>(params.get('sort') || 'latest');
  const [search, setSearch] = useState<string>(params.get('search') || '');

  useEffect(() => {
    setSearch(params.get('search') || '');
    setSelectedCategory(params.get('category') || 'all');
    setSortBy(params.get('sort') || 'latest');
  }, [params]);

  useEffect(() => {
    fetchProducts();
  }, [selectedCategory, sortBy, priceRange, search]);

  const fetchProducts = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('products')
        .select('id, name, slug, base_price, product_images(image_url, alt_text)');

      if (search) {
        query = query.or(`name.ilike.%${search}%,description.ilike.%${search}%`);
      }

      if (selectedCategory && selectedCategory !== 'all') {
        const category = categories.find((c) => c.slug === selectedCategory);
        if (category) {
          query = query.eq('category_id', category.id);
        }
      }

      query = query.gte('base_price', priceRange[0]).lte('base_price', priceRange[1]);

      switch (sortBy) {
        case 'price-asc':
          query = query.order('base_price', { ascending: true });
          break;
        case 'price-desc':
          query = query.order('base_price', { ascending: false });
          break;
        case 'name':
          query = query.order('name', { ascending: true });
          break;
        default:
          query = query.order('created_at', { ascending: false });
      }

      const { data, error } = await query;

      if (error) throw error;
      setProducts((data as Product[]) || []);
    } catch (error) {
      console.error('Error fetching products:', error);
    } finally {
      setLoading(false);
    }
  };

  const updateURL = (key: string, value: string) => {
    const current = new URLSearchParams(Array.from(params.entries()));
    if (value) {
      current.set(key, value);
    } else {
      current.delete(key);
    }
    const search = current.toString();
    const query = search ? `?${search}` : '';
    router.push(`/shop${query}`);
  };

  const handleCategoryChange = (category: string) => {
    setSelectedCategory(category);
    updateURL('category', category === 'all' ? '' : category);
  };

  const handleSortChange = (sort: string) => {
    setSortBy(sort);
    updateURL('sort', sort);
  };

  const FiltersContent = () => (
    <div className="space-y-6">
      <div>
        <h3 className="font-semibold mb-4 text-deep-forest">Category</h3>
        <RadioGroup value={selectedCategory} onValueChange={handleCategoryChange}>
          <div className="flex items-center space-x-2 mb-2">
            <RadioGroupItem value="all" id="all" />
            <Label htmlFor="all" className="cursor-pointer text-slate-bark">
              All Products
            </Label>
          </div>
          {categories.map((category) => (
            <div key={category.id} className="flex items-center space-x-2 mb-2">
              <RadioGroupItem value={category.slug} id={category.slug} />
              <Label htmlFor={category.slug} className="cursor-pointer">
                {category.name}
              </Label>
            </div>
          ))}
        </RadioGroup>
      </div>

      <div>
        <h3 className="font-semibold mb-4">Price Range</h3>
        <div className="space-y-4">
          <Slider
            value={priceRange}
            onValueChange={setPriceRange}
            max={5000}
            step={100}
            className="w-full"
          />
          <div className="flex justify-between text-sm text-gray-600">
            <span>{formatPrice(priceRange[0])}</span>
            <span>{formatPrice(priceRange[1])}</span>
          </div>
        </div>
      </div>

      <Button
        variant="outline"
        className="w-full"
        onClick={() => {
          setSelectedCategory('all');
          setPriceRange([0, 5000]);
          setSortBy('latest');
          router.push('/shop');
        }}
      >
        Clear Filters
      </Button>
    </div>
  );

  return (
    <div className="grid md:grid-cols-4 gap-8">
      <aside className="hidden md:block">
        <div className="sticky top-24 space-y-6">
          <FiltersContent />
        </div>
      </aside>

      <div className="md:col-span-3">
        <div className="flex justify-between items-center mb-6">
          <p className="text-slate-bark">
            {loading ? 'Loading...' : `${products.length} products found`}
          </p>
          <div className="flex gap-2 items-center">
            <Select value={sortBy} onValueChange={handleSortChange}>
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="Sort by" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="latest">Latest</SelectItem>
                <SelectItem value="price-asc">Price: Low to High</SelectItem>
                <SelectItem value="price-desc">Price: High to Low</SelectItem>
                <SelectItem value="name">Name: A to Z</SelectItem>
              </SelectContent>
            </Select>

            <Sheet>
              <SheetTrigger asChild>
                <Button variant="outline" size="icon" className="md:hidden">
                  <SlidersHorizontal className="h-5 w-5" />
                </Button>
              </SheetTrigger>
              <SheetContent side="left">
                <SheetHeader>
                  <SheetTitle className="text-deep-forest">Filters</SheetTitle>
                </SheetHeader>
                <div className="mt-6">
                  <FiltersContent />
                </div>
              </SheetContent>
            </Sheet>
          </div>
        </div>

        {loading ? (
          <div className="flex justify-center items-center h-64">
            <Loader2 className="h-8 w-8 animate-spin text-deep-forest" />
          </div>
        ) : products.length === 0 ? (
          <div className="text-center py-16">
            <p className="text-slate-bark mb-4">No products found matching your criteria.</p>
            <Button
              onClick={() => {
                setSelectedCategory('all');
                setPriceRange([0, 5000]);
                router.push('/shop');
              }}
              className="bg-deep-forest text-heirloom-white hover:bg-oxide-brown"
            >
              Clear Filters
            </Button>
          </div>
        ) : (
          <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {products.map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
